return {["fb216_01"]={["down"]=[[fb216_02]],["dsc"]=[[这便是凌府宅门。三级石阶前两座石狮并排而立，石狮身后的壁上又雕刻有青松仙鹤图。远远就能看到那飞翘的檐角左右各挂着一盏写有“凌”字的红色灯笼。]],["id"]=[[fb216_01]],["name"]=[[凌府大门]],["stepMusic"]=[[jiaobu]],["up"]=[[fb216_24]]},["fb216_02"]={["down"]=[[fb216_04]],["dsc"]=[[略微曲折的走廊，粉墙黛瓦，右侧墙上悬挂着古时书画拓本，左侧可见府内假山上的乘凉的小亭。]],["id"]=[[fb216_02]],["name"]=[[走廊]],["role1"]=[[szjnpc2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb216_01]]},["fb216_03"]={["down"]=[[fb216_06]],["dsc"]=[[监牢内的守卫房。几张木板搭成的床榻有序放置，但被褥乱扔，床前的两张木桌上还堆满了啃过的肉骨，因地处潮湿，总有股熏鼻之味。]],["id"]=[[fb216_03]],["name"]=[[守卫房]],["role1"]=[[szjnpc1]],["role2"]=[[szjnpc1a]],["stepMusic"]=[[jiaobu]]},["fb216_04"]={["down"]=[[fb216_09]],["dsc"]=[[略微曲折的走廊，粉墙黛瓦，右侧墙上悬挂着古时书画拓本，左侧可见府内假山上的乘凉的小亭。]],["id"]=[[fb216_04]],["name"]=[[走廊]],["right"]=[[fb216_05]],["stepMusic"]=[[jiaobu]],["up"]=[[fb216_02]]},["fb216_05"]={["dsc"]=[[略微曲折的走廊，粉墙黛瓦，右侧墙上悬挂着古时书画拓本，左侧可见府内假山上的乘凉的小亭。]],["id"]=[[fb216_05]],["left"]=[[fb216_04]],["name"]=[[走廊]],["right"]=[[fb216_06]],["stepMusic"]=[[jiaobu]]},["fb216_06"]={["dsc"]=[[凌府内关押囚犯的监牢大门，平日里有守卫看守。地上散落着不少杂草，门内光线昏暗，让人生畏。]],["id"]=[[fb216_06]],["item1"]=[[szjdj9]],["left"]=[[fb216_05]],["name"]=[[监牢大门]],["right"]=[[fb216_07]],["stepMusic"]=[[jiaobu]],["up"]=[[fb216_03]]},["fb216_07"]={["dsc"]=[[监牢内的走道，由几个火盆照亮，不时还会窜出一两只硕大的老鼠。]],["id"]=[[fb216_07]],["item1"]=[[szjdj4]],["left"]=[[fb216_06]],["name"]=[[走道]],["right"]=[[fb216_08]],["stepMusic"]=[[jiaobu]]},["fb216_08"]={["down"]=[[fb216_12]],["dsc"]=[[监牢内的走道，由几个火盆照亮，不时还会窜出一两只硕大的老鼠。]],["id"]=[[fb216_08]],["item1"]=[[szjdj26]],["left"]=[[fb216_07]],["name"]=[[走道]],["stepMusic"]=[[jiaobu]]},["fb216_09"]={["down"]=[[fb216_16]],["dsc"]=[[凌府内专门用来会客的地方，摆设物件均是上等楠木，一侧的古董字画也均是价值连城。若非知凌府主人不过知府之职，定会以为来到了王府大宅。]],["id"]=[[fb216_09]],["item1"]=[[szjdj15]],["item2"]=[[szjdj27]],["name"]=[[正厅]],["role1"]=[[szjnpc3]],["stepMusic"]=[[jiaobu]],["up"]=[[fb216_04]]},["fb216_10"]={["dsc"]=[[若不打开牢门，则这牢房内毫无光亮，密闭而不透气，寻常人怕不过多时就会窒息而死。奇怪的是，不知为何牢房内会栓有一根红线，扯动线绳，牢门外的铃铛就会响起。]],["id"]=[[fb216_10]],["name"]=[[密闭牢房]],["right"]=[[fb216_11]],["stepMusic"]=[[jiaobu]]},["fb216_11"]={["dsc"]=[[监牢内的走道，由几个火盆照亮，不时还会窜出一两只硕大的老鼠。]],["id"]=[[fb216_11]],["item1"]=[[szjdj12]],["left"]=[[fb216_10]],["name"]=[[走道]],["right"]=[[fb216_12]],["stepMusic"]=[[jiaobu]]},["fb216_12"]={["down"]=[[fb216_19]],["dsc"]=[[监牢内的走道，由几个火盆照亮，不时还会窜出一两只硕大的老鼠。]],["id"]=[[fb216_12]],["item1"]=[[szjdj6]],["left"]=[[fb216_11]],["name"]=[[走道]],["right"]=[[fb216_13]],["stepMusic"]=[[jiaobu]],["up"]=[[fb216_08]]},["fb216_13"]={["dsc"]=[[普通的牢房，专门关押得罪凌知府的囚犯。因身处凌府，外人少有知道，枯骨成堆也未可知。]],["id"]=[[fb216_13]],["left"]=[[fb216_12]],["name"]=[[牢房]],["role1"]=[[szjnpc4]],["stepMusic"]=[[jiaobu]]},["fb216_14"]={["dsc"]=[[凌府刚刚布置下的灵堂，掀开白帘，正中大大的“奠”字前立有“爱女之位”的牌位。中间一个寻常棺椁，整个灵堂内寂静无声，堂前烧纸的火盆内空空如也。]],["id"]=[[fb216_14]],["item1"]=[[szjdj32]],["name"]=[[灵堂]],["right"]=[[fb216_25]],["stepMusic"]=[[jiaobu]]},["fb216_15"]={["dsc"]=[[略微曲折的走廊，粉墙黛瓦，右侧墙上悬挂着古时书画拓本，左侧可见府内假山上的乘凉的小亭。]],["id"]=[[fb216_15]],["left"]=[[fb216_25]],["name"]=[[走廊]],["right"]=[[fb216_16]],["role1"]=[[szjnpc1g]],["stepMusic"]=[[jiaobu]]},["fb216_16"]={["dsc"]=[[相较前厅，虽因一桌棋盘摆放稍显雅致，但因棋子皆为玉石所制，连寻常府宅装饰摆放的花束也为玉石造成，又足见奢靡沾俗。]],["id"]=[[fb216_16]],["left"]=[[fb216_15]],["name"]=[[后厅]],["right"]=[[fb216_17]],["role1"]=[[szjnpc2b]],["stepMusic"]=[[jiaobu]],["up"]=[[fb216_09]]},["fb216_17"]={["dsc"]=[[凌府花园内中满了罕有的名花，世上难得一见。姑苏内早有传闻，连皇宫御花园内的花卉也不及此处，许多爱花人若想前来一观，皆被拒之门外。]],["id"]=[[fb216_17]],["item1"]=[[szjdj1]],["item2"]=[[szjdj1]],["item3"]=[[szjdj8a]],["left"]=[[fb216_16]],["name"]=[[花园]],["rightDown"]=[[fb216_21]],["role1"]=[[szjnpc6]],["stepMusic"]=[[jiaobu]]},["fb216_18"]={["dsc"]=[[牢房内十分宽阔，一个巨大的木床上铺满了杂草，壁上则嵌入了几道足有手臂粗壮的长铁链，专门用来锁住囚犯。即便是武林高手，也难以从此牢中脱逃。牢中恍如绝境，但一侧的气窗外却可见凌府二楼的窗槛，似一线生机。]],["id"]=[[fb216_18]],["item1"]=[[szjdj2]],["item2"]=[[szjdj13]],["item3"]=[[szjdj14]],["item4"]=[[szjdj41]],["item5"]=[[szjdj47]],["item6"]=[[szjdj49]],["name"]=[[特制牢房]],["right"]=[[fb216_19]],["stepMusic"]=[[jiaobu]]},["fb216_19"]={["down"]=[[fb216_22]],["dsc"]=[[监牢内的走道，由几个火盆照亮，不时还会窜出一两只硕大的老鼠。]],["id"]=[[fb216_19]],["item1"]=[[szjdj7]],["left"]=[[fb216_18]],["name"]=[[走道]],["right"]=[[fb216_20]],["stepMusic"]=[[jiaobu]],["up"]=[[fb216_12]]},["fb216_20"]={["dsc"]=[[普通的牢房，专门关押得罪凌知府的囚犯。因身处凌府，外人少有知道，枯骨成堆也未可知。]],["id"]=[[fb216_20]],["left"]=[[fb216_19]],["name"]=[[牢房]],["role1"]=[[szjnpc5]],["stepMusic"]=[[jiaobu]]},["fb216_21"]={["down"]=[[fb216_23]],["dsc"]=[[凌府花楼，楼内也放有些许花卉点缀，从此推窗而望，一步一景，可将花园览遍。楼内又设有贵妃椅一张，琴瑟在侧，即便无人，下人门也常年焚香以待。]],["id"]=[[fb216_21]],["leftUp"]=[[fb216_17]],["name"]=[[花楼]],["role1"]=[[szjnpc2a]],["stepMusic"]=[[jiaobu]]},["fb216_22"]={["dsc"]=[[监牢深处的刑台，一架十字桩上挂满了沾血的铁链，一旁刑具一应俱全。见此情景，未上刑台，先惧三分。]],["id"]=[[fb216_22]],["name"]=[[监牢刑台]],["stepMusic"]=[[jiaobu]],["up"]=[[fb216_19]]},["fb216_23"]={["dsc"]=[[一道长梯弯折后抵达二楼。楼内放有一方书案，旁侧书架上经史子集俱全。从二楼窗槛上推窗，可府览整个凌府，尤其是这窗口正对一个小小气窗。]],["id"]=[[fb216_23]],["item1"]=[[szjdj3]],["name"]=[[花楼二楼]],["stepMusic"]=[[jiaobu]],["up"]=[[fb216_21]]},["fb216_24"]={["id"]=[[fb216_24]],["item1"]=[[szjdj48]],["name"]=[[狮子林]],["stepMusic"]=[[jiaobu]]},["fb216_25"]={["dsc"]=[[监牢内的走道，由几个火盆照亮，不时还会窜出一两只硕大的老鼠。]],["id"]=[[fb216_25]],["item1"]=[[szjdj43]],["left"]=[[fb216_14]],["name"]=[[走廊]],["right"]=[[fb216_15]],["stepMusic"]=[[jiaobu]]}}000